<div class="toolbar"><span class="grow muted small">Newsletters and announcements to subscribed contacts, with open and click tracking and one-click unsubscribe.</span><a class="btn btn-primary btn-sm" href="/admin/campaigns/new"><?= icon('plus', 15) ?> New campaign</a></div>
<div class="table-wrap"><table class="t"><thead><tr><th>Campaign</th><th>Status</th><th class="num">Recipients</th><th class="num">Sent</th><th class="num">Opened</th><th class="num">Clicked</th><th></th></tr></thead><tbody>
<?php foreach ($items as $c): $t = max(1, (int) $c['total']); ?><tr><td><strong><?= e($c['name']) ?></strong><div class="muted xs"><?= e($c['subject']) ?> · <?= e(ago($c['created_at'])) ?></div></td><td><?= badge($c['status'], ['sent' => 'green', 'sending' => 'amber', 'draft' => ''][$c['status']] ?? '') ?></td><td class="num"><?= (int) $c['total'] ?></td><td class="num"><?= (int) $c['sent'] ?></td><td class="num"><?= $c['total'] ? (int) $c['opens'] . ' (' . round($c['opens'] * 100 / $t) . '%)' : '—' ?></td><td class="num"><?= $c['total'] ? (int) $c['clicks'] . ' (' . round($c['clicks'] * 100 / $t) . '%)' : '—' ?></td><td><a class="rowbtn" href="/admin/campaigns/<?= (int) $c['id'] ?>">Open</a></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="7" class="muted center" style="padding:30px">No campaigns yet.</td></tr><?php endif; ?></tbody></table></div>
